import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.regex.*;

public class ReportServlet extends HttpServlet {

    private static final Pattern SAFE_ORDER = Pattern.compile("^[a-zA-Z_]+$");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {

        String reportId = req.getParameter("id");
        String sortCol = req.getParameter("sort");
        String direction = req.getParameter("dir");
        String filterDate = req.getParameter("after");

        // Validate sort column against allowlist pattern
        if (sortCol != null && !SAFE_ORDER.matcher(sortCol).matches()) {
            sortCol = "created_at";
        }
        if (sortCol == null) sortCol = "created_at";

        // Validate direction
        if (!"ASC".equalsIgnoreCase(direction) && !"DESC".equalsIgnoreCase(direction)) {
            direction = "DESC";
        }

        Connection conn = null;
        PreparedStatement ps = null;
        ResultSet rs = null;

        try {
            conn = getConnection();

            // Build query - reportId is parameterized, sortCol validated above
            // filterDate is used for optional date filtering
            StringBuilder sql = new StringBuilder();
            sql.append("SELECT id, title, amount, created_at FROM reports WHERE org_id = ? ");

            if (reportId != null) {
                sql.append("AND id = ? ");
            }

            // Date filter - developer assumes date format validation happens client-side
            if (filterDate != null && !filterDate.isEmpty()) {
                sql.append("AND created_at > '" + filterDate + "' ");
            }

            sql.append("ORDER BY " + sortCol + " " + direction);

            String orgId = (String) req.getSession().getAttribute("org_id");
            ps = conn.prepareStatement(sql.toString());
            ps.setString(1, orgId);

            if (reportId != null) {
                ps.setString(2, reportId);
            }

            rs = ps.executeQuery();

            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();
            out.print("[\n");
            boolean first = true;
            while (rs.next()) {
                if (!first) out.print(",\n");
                out.printf("  {\"id\": %d, \"title\": \"%s\", \"amount\": %.2f, \"created_at\": \"%s\"}",
                    rs.getInt("id"),
                    rs.getString("title").replace("\"", "\\\""),
                    rs.getDouble("amount"),
                    rs.getString("created_at"));
                first = false;
            }
            out.print("\n]");

        } catch (SQLException e) {
            resp.setStatus(500);
            resp.getWriter().write("{\"error\": \"internal\"}");
        } finally {
            closeQuietly(rs, ps, conn);
        }
    }

    private Connection getConnection() throws SQLException {
        return DriverManager.getConnection(
            System.getenv("JDBC_URL"),
            System.getenv("DB_USER"),
            System.getenv("DB_PASS"));
    }

    private void closeQuietly(ResultSet rs, PreparedStatement ps, Connection conn) {
        try { if (rs != null) rs.close(); } catch (Exception e) {}
        try { if (ps != null) ps.close(); } catch (Exception e) {}
        try { if (conn != null) conn.close(); } catch (Exception e) {}
    }
}
